examples.template:
Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2)) {
    Box {
        MonarchIconButton(label = "Notifications", onClick = {}) {
            MonarchIcon(SampleIcons.Bell, contentDescription = null)
        }
        MonarchBadge(
            text = items.count { !it.read && it.id !in read }.toString(),
            modifier = Modifier.align(Alignment.TopEnd),
            tone = MonarchTone.Danger,
            variant = MonarchBadgeVariant.Solid,
            size = MonarchBadgeSize.Sm,
        )
    }
    Box(
        modifier = Modifier
            .fillMaxWidth()
            .border(1.dp, MonarchTheme.colors.borderSubtle, MonarchTheme.shapes.lg),
    ) {
    MonarchNotificationCenter(
        items = items,
        modifier = Modifier.fillMaxWidth().heightIn(max = 680.dp),
        now = {{now|millis}},
        hasMore = {{hasMore}},
        onMarkRead = { read = read + it },
        onMarkAllRead = { read = items.map { it.id }.toSet() },
        onLoadMore = {},
        onSelect = { /* Open what the notification is about. */ },
        footer = { MonarchLink(text = {{footer}}, onClick = {}, variant = MonarchLinkVariant.Standalone) },
    )
    }
}

